#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <cmath>

int calculate(int op1, int op2, char op) {
    switch (op) {
        case '+': return op1 + op2;
        case '-': return op1 - op2;
        case '*': return op1 * op2;
        case '/': return (op2 != 0) ? (op1 / op2) : 0;
        case '%': return (op2 != 0) ? (op1 % op2) : 0;
        case '^': return static_cast<int>(std::pow(op1, op2));
        default:  return 0;
    }
}

int evaluatePostfix(const std::string& expr) {
    std::vector<int> stack;
    std::istringstream iss(expr);
    std::string token;

    while (iss >> token) {
        if (token.size() == 1 && std::string("+-*/%^").find(token[0]) != std::string::npos) {
            int x = stack.back(); stack.pop_back(); // right operand
            int y = stack.back(); stack.pop_back(); // left operand
            stack.push_back(calculate(y, x, token[0]));
        } else {
            stack.push_back(std::stoi(token));
        }
    }
    return stack.empty() ? 0 : stack.back();
}

int main() {
    // Biểu thức trung tố: (6 + 2) * 5 - 8 / 4
    // Tương đương hậu tố: 6 2 + 5 * 8 4 / -
    std::string postfixExpr = "6 2 + 5 * 8 4 / -";
    int result = evaluatePostfix(postfixExpr);

    std::cout << "Postfix: " << postfixExpr << "\n";
    std::cout << "Result: " << result << "\n";
    return 0;
}

#include <iostream>
#include <memory>
#include <queue>
#include <string>

struct TreeNode {
    int data;
    std::unique_ptr<TreeNode> left;
    std::unique_ptr<TreeNode> right;
    explicit TreeNode(int val) : data(val), left(nullptr), right(nullptr) {}
};

void insertBST(std::unique_ptr<TreeNode>& root, int val) {
    if (!root) {
        root = std::make_unique<TreeNode>(val);
    } else if (val < root->data) {
        insertBST(root->left, val);
    } else {
        insertBST(root->right, val);
    }
}

void levelOrder(const TreeNode* root) {
    if (!root) return;
    std::queue<const TreeNode*> q;
    q.push(root);
    bool first = true;
    while (!q.empty()) {
        const TreeNode* curr = q.front();
        q.pop();
        if (!first) std::cout << " ";
        std::cout << curr->data;
        first = false;
        if (curr->left) q.push(curr->left.get());
        if (curr->right) q.push(curr->right.get());
    }
    std::cout << "\n";
}

void outputTree(const TreeNode* root, int totalSpaces) {
    if (!root) return;
    outputTree(root->right.get(), totalSpaces + 5);
    std::cout << std::string(totalSpaces, ' ') << root->data << "\n";
    outputTree(root->left.get(), totalSpaces + 5);
}

int main() {
    std::unique_ptr<TreeNode> root = nullptr;
    // Nạp một tập hợp giá trị tương tự hình 12.22
    int values[] = {49, 28, 83, 18, 40, 71, 97};
    for (int v : values) {
        insertBST(root, v);
    }

    std::cout << "Level-order Traversal:\n";
    levelOrder(root.get());

    std::cout << "\nHorizontal Tree Visualization:\n";
    outputTree(root.get(), 0);
    return 0;
}
